INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(535, 'koKR', 'Valik', 'Uhhh... Ranny, umierający i do tego twarzą w twarz z wrogiem.$b$bPewnie i tak mnie zabijesz, ale jeśli przyniesiesz mi trochę portera z Południowego Brzegu – twoi też piją, co nie? – powiem ci, co chcesz wiedzieć.', 'Zanieś kufel portera z Południowego Brzegu Valikowi w obozie Syndykatu.', '', 'Wróć do poplecznika Valika na Przylądku Sofery w Górach Alterak.', '', '', '', '', 0),
(602, 'koKR', 'Analiza magiczna', 'Z tego, co słyszałem, magom z Dalaranu udało się odbudować swoje magiczne miasto i przenieść je do Północnej Grani, zostawiając po sobie ogromny krater. Niektórzy magowie jednak tu zostali i mogliby poświęcić trochę czasu, żeby przyjrzeć się tym karwaszom. Jeśli wiem cokolwiek o magach, to tyle, że nie potrafią się oprzeć magicznej zagadce.$b$bWeź worek karwaszy wodnych żywiołaków i sprawdź, czy rzucą jakieś światło na klątwę Kamienia. Odszukaj arcymaga Ansirema Runotkacza. Miałem już z nim do czynienia, a jego wiedza jest ogromna.', 'Zanieś karwasze wodnych żywiołaków arcymagowi Ansiremowi Runotkaczowi w Dalarańskim Kraterze.', '', 'Złóż raport arcymagowi Ansiremowi Runotkaczowi w Dalarańskim Kraterze w Górach Alterak.', '', '', '', '', 0),
(603, 'koKR', 'Klucz Ansirema', 'Mag, który ma Kamień, wzmacnia jego moc przez jakiś punkt skupienia... pewnie jakiś ołtarz. Powinno ci się udać go zakłócić, jeśli go przeciążysz.$b$bTak się składa, że wiem, co się do tego nada: starożytny sztylet, kolejna trollowa relikwia. Jest tylko jeden... drobny problem.$b$bWidzisz, znalazłem ten sztylet podczas badań w Cierniodławach, ale dałem go mojej upartej córce, Catelyn, która uciekła do Łupieżczej Zatoki, żeby zostać piratką.', 'Porozmawiaj z Catelyn w Łupieżczej Zatoce.', '', 'Porozmawiaj z Catelyn w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(1712, 'koKR', 'Cyklonian', 'Od wieków obserwuję to miejsce. Obserwuję, bo pewnego dnia chcę ujrzeć upadek wielkiego Cykloniana. Ale nie znalazłem jeszcze czempiona, który pokonałby władcę wiatru.$B$BMoże ty nim jesteś.$B$BUdowodnij mi to. Zbierz przedmioty, których potrzebuję, by przyzwać Cykloniana, a przekonam się, że jesteś $gwielkim wojownikiem:wielką wojowniczką;. Może wtedy zdołasz go pokonać i zdobyć jego serce wiru.$B$BJeśli tak się stanie, tchnę moc serca w broń i ci ją oddam.$B$BOto pergamin z listą przedmiotów, których potrzebuję.', 'Przynieś przedmioty wymienione w Pergaminie Bath\'raha Bath\'rahowi Wiatrowidzowi w Górach Alterak.', '', '', '', '', '', '', 0),
(1713, 'koKR', 'Przyzwanie', 'Jestem gotów odprawić rytuał przyzwania Cykloniana. Gdy się pojawi, musisz go pokonać i zabrać jego serce wiru. Użyję go, by tchnąć w broń moc Cykloniana.$B$B$N, czy jesteś $ggotów:gotowa; stawić czoła władcy wiatru?', 'Przynieś Serce wiru Bath\'rahowi Wiatrowidzowi.', '', '', '', '', '', '', 0),
(1714, 'koKR', 'Esencja wygnańca', '', '', '', 'Wróć do Kotła Bath\'raha w Górach Alterak.', '', '', '', '', 0),
(1792, 'koKR', 'Broń wiru', '', '', '', '', '', '', '', '', 0),
(6681, 'koKR', 'Dwór Krukowiska', '$N,$B$BKrukowisko zainteresowało się tobą, $gmłody złodzieju:młoda złodziejko;. Obserwowaliśmy cię. Twój styl jest jeszcze nieco niezgrabny, ale nie ma w nim nic, czego nie dałoby się poprawić.$B$BJeśli chcesz rozpocząć karierę jako $guczeń:uczennica; mistrza Krukowiska i $gczłonek:członkini; Ligi Zabójców, wystarczy, że przyniesiesz Pieczęć Krukowiska (dołączoną do tego listu) do Dworu Krukowiska.$B$BTwoim pierwszym zadaniem jest odnaleźć dwór, ukryty wśród wzgórz Międzygórza, i wykazać się przebiegłością.$B$BZ wyrazami szacunku$B$BFahrad', 'Zanieś Pieczęć Krukowiska Fahradowi we Dworze Krukowiska, ukrytym wśród wzgórz Międzygórza.$B$BPo drodze twoja przebiegłość zostanie wystawiona na próbę. Bądź $ggotów:gotowa;.', '', 'Wróć do Fahrada we Dworze Krukowiska w Międzygórzu.', '', 'Obrzęd przebiegłości', '', '', 0),
(7081, 'koKR', 'Cmentarze Doliny Alterak', 'Cmentarze w Dolinie Alterak to cenne tereny. Zarówno Horda, jak i Przymierze zażarcie walczą o te uświęcone ziemie. Czy ty, $N, jesteś $ggotów:gotowa; przyłączyć się do tej walki?$B$BChcę, żebyś $gzaatakował:zaatakowała; wrogi cmentarz. Znajdź cmentarz, na którym stoi sztandar Hordy, i wyrwij go z ziemi! Zrób to, a twoje zadanie będzie wykonane...$B$BAle jeśli zdołasz jeszcze utrzymać cmentarz przez kilka minut, wkrótce przybędą nasze oddziały, by cię zluzować.', 'Zaatakuj cmentarz, a następnie wróć do sierżanta Durgena Gromdardy w Górach Alterak.', '', 'Wróć do sierżanta Durgena Gromdardy w Dalarańskim Kraterze w Górach Alterak.', 'Zaatakowany cmentarz', '', '', '', 0),
(7082, 'koKR', 'Cmentarze Alterak', 'Linie frontu w Dolinie Alterak ciągle się przesuwają. Tereny przechodzą z rąk do rąk, gdy ścieramy się z przeciwnikami w śmiertelnej walce. A to na cmentarzach, $N, bitwy są najzacieklejsze.$B$BChcę, żebyś $gzaatakował:zaatakowała; cmentarz należący do Przymierza! Znajdź cmentarz, na którym stoi sztandar Przymierza, i wyrwij go z ziemi.$B$BZrób to, a twoje zadanie dla mnie będzie wykonane, ale... jeśli utrzymasz cmentarz przez kilka minut, będzie nasz, a nasze oddziały przybędą, by cię zluzować.', 'Zaatakuj cmentarz, a następnie wróć do kapral Teeki Krwawy Warkot w Górach Alterak.', '', 'Wróć do kapral Teeki Krwawy Warkot w Górach Alterak.', 'Zaatakowany cmentarz', '', '', '', 0),
(7101, 'koKR', 'Wieże i bunkry', 'Wieże i bunkry to ważne pozycje i musimy zdobyć i utrzymać je wszystkie! Dlatego chcę, żebyś $gzaatakował:zaatakowała; bunkier kontrolowany przez wroga.$B$BAby to zrobić, wejdź do bunkra ze sztandarem Przymierza. W środku zobaczysz kolejny sztandar. Wyrwij go, a na jego miejscu pojawi się biały sztandar Hordy. Dobra robota!$B$BWtedy twoje zadanie dla mnie będzie wykonane, ale jeśli utrzymasz to miejsce wystarczająco długo i Przymierze go nie odbije, zostanie zniszczone!', 'Zdobądź wrogą wieżę, a następnie wróć do kapral Teeki Krwawy Warkot w Górach Alterak.', '', 'Wróć do kapral Teeki Krwawy Warkot w Górach Alterak.', 'Zdobyta wieża', '', '', '', 0),
(7102, 'koKR', 'Wieże i bunkry', 'Wieże i bunkry to kluczowe pozycje obronne, więc musimy utrzymać ich jak najwięcej! Chcę, żebyś $gzaatakował:zaatakowała; wieżę lub bunkier w Dolinie Alterak.$B$BAby to zrobić, wejdź do wieży, na której szczycie powiewa sztandar Hordy. W środku zobaczysz kolejny wrogi sztandar. Wyrwij go, a na jego miejscu pojawi się biały sztandar Przymierza. Dobra robota!$B$BWtedy twoja misja dla mnie będzie wykonana, ale utrzymaj ten teren wystarczająco długo, a jeśli Horda go nie odbije, zostanie zniszczony!', 'Zniszcz sztandar we wrogiej wieży lub bunkrze, a następnie wróć do sierżanta Durgena Gromdardy w Górach Alterak.', '', 'Wróć do sierżanta Durgena Gromdardy w Dalarańskim Kraterze w Górach Alterak.', 'Zniszczony sztandar', '', '', '', 0),
(7122, 'koKR', 'Przejmij kopalnię', 'Kopalnie w Dolinie Alterak kryją coś więcej niż tylko minerały. Zarówno Mroźne Wilki, jak i Gromdarda ukryli nadwyżki zapasów w Kopalni Żelaznej Głębi i Kopalni Mrozokłów... niezły pomysł, gdybyśmy tylko mogli utrzymać nad nimi kontrolę!$B$BPrzejmij kopalnię, a potem wróć do mnie. Aby przejąć kopalnię, wejdź do takiej, której nie kontrolujemy, i zabij jej przywódcę. Wtedy kopalnia będzie nasza, a my wyślemy oddziały, żeby jej strzegły!', 'Przejmij kopalnię, której nie kontroluje Gromdarda, a następnie wróć do sierżanta Durgena Gromdardy w Górach Alterak.', '', 'Wróć do sierżanta Durgena Gromdardy w Dalarańskim Kraterze w Górach Alterak.', 'Przejęta kopalnia', '', '', '', 0),
(7124, 'koKR', 'Przejmij kopalnię', 'Bitwa szaleje w całej Dolinie Alterak, także w Kopalni Mrozokłów i Kopalni Żelaznej Głębi. Obie są bogatymi źródłami minerałów i obie służą za składy zapasów – nic dziwnego, że są tak cenne!$B$BWesprzyj nasz wysiłek wojenny, $N! Przejmij jedną z kopalń dla Hordy! Aby przejąć kopalnię, wejdź do takiej, której nie kontrolujemy, i zabij jej przywódcę. Wtedy kopalnia będzie nasza, a my wyślemy oddziały, żeby jej strzegły!', 'Przejmij kopalnię, a następnie wróć do kapral Teeki Krwawy Warkot w Górach Alterak.', '', 'Wróć do kapral Teeki Krwawy Warkot w Górach Alterak.', 'Przejęta kopalnia', '', '', '', 0),
(7141, 'koKR', 'Bitwa w Alterak', 'Liga Odkrywców uważa, że w Dolinie Alterak są artefakty, ale orkowie z Mroźnych Wilków nie pozwalają nam jej badać. Nie możemy pozwolić, by Horda przeszkadzała nam w naukowych dociekaniach! Pokonaj generała Mroźnych Wilków, Drek\'Thara. Gdy zginie, orkowie stracą przewagę.$B$BDrek\'Thar jest w Twierdzy Mroźnych Wilków, na południu Doliny Alterak. Pokonaj go, a potem wróć do mnie.', 'Wejdź do Doliny Alterak, pokonaj generała Hordy Drek\'thara, a następnie wróć do poszukiwaczki Łupikamień w Górach Alterak.', 'Pokonaj Drek\'thara.', 'Wróć do poszukiwaczki Łupikamień.', '', '', '', '', 0),
(7142, 'koKR', 'Bitwa o Alterak', 'Krasnoludy z Gromdardy i ich sojusznicy najechali Dolinę Alterak i musimy ich wypędzić! Aby wygrać bitwę o Alterak, musimy pokonać ich generała, Vandara Gromdardę!$B$BZnajdziesz Vandara w Dun Baldar, na północy Doliny Alterak.$B$BZniszcz go, $N, a potem wróć do mnie.', 'Wejdź do Doliny Alterak i pokonaj krasnoludzkiego generała, Vandara Gromdardę. Następnie wróć do Voggaha Śmiertelnego Chwytu w Górach Alterak.', 'Pokonaj Vandara Gromdardę.', 'Wróć do Voggaha Śmiertelnego Chwytu w Górach Alterak.', '', '', '', '', 0),
(7161, 'koKR', 'Próba bojowa', 'Witaj, $N. Dawno nie mieliśmy okazji odpowiedzieć na zew bitwy. Dawne uczucia budzą się powoli, ale gdy już się obudzą, krew zaczyna szybciej płynąć. Wraca bitewny szał...$B$BKażdy nowy przybysz w Dolinie musi najpierw przejść bitewny obrzęd.$B$BGłęboko w jaskini gnoli z Dzikołapych znajduje się sztandar Mroźnych Wilków. Wyrusz tam i odzyskaj sztandar. Przynieś mi go, a nadam ci insygnia adepta Mroźnych Wilków.', 'Udaj się do Pieczary Dzikołapych na południowy wschód od głównej bazy w Dolinie Alterak i znajdź Sztandar Mroźnych Wilków. Przynieś Sztandar Mroźnych Wilków mistrzowi wojennemu Laggrondowi.', '', 'Wróć do mistrza wojennego Laggronda w Górach Alterak.', '', '', '', '', 0),
(7162, 'koKR', 'Próba bojowa', '$GPrzybyłeś:Przybyłaś; w samą porę, $N. Te dzikusy z Mroźnych Wilków po prostu nie chcą się poddać! Musimy pokazać im potęgę Gromdardy. Muszą ugiąć karku przed naszą wyższością.$B$BZanim wyruszysz na pole bitwy, zechcesz zapewne wstąpić w szeregi Gromdardy.$B$BNa południowy zachód od Dun Baldar znajdziesz Pieczarę Lodowego Skrzydła. Głęboko w pieczarze zatknięto Sztandar Gromdardy. Wyrusz tam i odzyskaj ten sztandar. Przynieś mi go, a zasłużysz na insygnia adepta Gromdardy.', 'Udaj się do Pieczary Lodowego Skrzydła na południowy zachód od Dun Baldar w Dolinie Alterak i odzyskaj Sztandar Gromdardy. Przynieś Sztandar Gromdardy porucznikowi Haggerdinowi w Górach Alterak.', '', 'Wróć do porucznika Haggerdina na Wzgórzu Darrow w Międzygórzu.', '', '', '', '', 0),
(7163, 'koKR', 'Powstań i zyskaj uznanie', '', '', '', 'Wróć do mistrza wojennego Laggronda w Górach Alterak.', '', '', '', '', 0),
(7164, 'koKR', 'Szacunek klanu', '', '', '', 'Wróć do mistrza wojennego Laggronda w Górach Alterak.', '', '', '', '', 0),
(7165, 'koKR', 'Zasłużona cześć', '', '', '', 'Wróć do mistrza wojennego Laggronda w Górach Alterak.', '', '', '', '', 0),
(7166, 'koKR', 'Legendarni bohaterowie', '', '', '', 'Wróć do mistrza wojennego Laggronda w Górach Alterak.', '', '', '', '', 0),
(7167, 'koKR', 'Oko Dowodzenia', '', '', '', 'Wróć do mistrza wojennego Laggronda w Górach Alterak.', '', '', '', '', 0),
(7168, 'koKR', 'Powstań i zyskaj uznanie', '', '', '', 'Wróć do porucznika Haggerdina w Górach Alterak.', '', '', '', '', 0),
(7169, 'koKR', 'Szacunek Straży', '', '', '', 'Wróć do porucznika Haggerdina w Górach Alterak.', '', '', '', '', 0),
(7170, 'koKR', 'Zasłużona cześć', '', '', '', 'Wróć do porucznika Haggerdina w Górach Alterak.', '', '', '', '', 0),
(7171, 'koKR', 'Legendarni bohaterowie', '', '', '', 'Wróć do porucznika Haggerdina w Górach Alterak.', '', '', '', '', 0),
(7172, 'koKR', 'Oko Dowodzenia', '', '', '', 'Wróć do porucznika Haggerdina w Górach Alterak.', '', '', '', '', 0),
(7181, 'koKR', 'Legenda Korraka', 'Najeźdźcy z Gromdardy nie są jedynym zagrożeniem w tym regionie, $gżołnierzu:żołnierko;. Wojna w Dolinie toczy się na dwóch frontach. O władzę walczą też trolle ludożercy z Zimowego Topora.$B$BPrzewodzi im Korrak Krwawy Szaleniec – okrutna i przebiegła bestia.$B$BUderzenie w Korraka mogłoby okazać się miażdżącym ciosem dla klanu Zimowego Topora. Zabij bestię, a zostaniesz $gnagrodzony:nagrodzona;!', 'Legenda głosi, że przywódca potężnych trolli z Zimowego Topora pojawia się, kiedy zechce, by siać spustoszenie wśród mieszkańców Doliny Alterak.$B$BJeśli Korrak się pokaże, zabij go i wróć do mistrza wojennego Laggronda.', '', 'Wróć do mistrza wojennego Laggronda w Górach Alterak.', '', '', '', '', 0),
(7202, 'koKR', 'Korrak Krwawy Szaleniec', 'Rdzenne trolle z Zimowego Topora to bezwzględne dzikusy, które najchętniej wrzuciłyby nasze kości do swojego ohydnego gulaszu.$B$BMusimy pokazać im naszą siłę!$B$BW ich jaskiniach odzyskaliśmy księgi, które opisują hierarchię ich przywódców. Z tych artefaktów wynika, że ich wódz, Korrak Krwawy Szaleniec, zwykle pozostaje w ukryciu, dopóki nie dostanie powodu, by się ujawnić.$B$BŚmierć Korraka oznaczałaby śmierć klanu Zimowego Topora! Zabij go i wróć.', 'Legenda głosi, że przywódca potężnych trolli z Zimowego Topora pojawia się, kiedy zechce, by siać spustoszenie wśród mieszkańców Doliny Alterak.$B$BJeśli Korrak się pokaże, zabij go i wróć do porucznika Haggerdina w Górach Alterak.', '', 'Wróć do porucznika Haggerdina na Wzgórzu Darrow w Międzygórzu.', '', '', '', '', 0),
(7381, 'koKR', 'Powrót Korraka', 'To prawda, że Korrak zginął, ale pozostaje jedno pytanie: czy pozostanie martwy? Trolle słyną ze swojej plemiennej magii nie z tego świata. Nie zdziwiłbym się, gdyby poległego przywódcę wskrzeszono, by znów rządził swoim klanem.$B$BWiesz, co robić, jeśli to się kiedyś stanie.$B$B<Mistrz wojenny Laggrond przeciąga palcem wskazującym po szyi.>$B$BI tym razem chcę jego czaszkę. Po prostu miej oczy szeroko otwarte, $gżołnierzu:żołnierko;.$B$BOdmaszerować!', 'Jeśli Korrak Krwawy Szaleniec powróci na Pole Niezgody, odszukaj go i zabij.$B$BPrzynieś Czaszkę Korraka mistrzowi wojennemu Laggrondowi w Międzygórzu.', '', 'Wróć do mistrza wojennego Laggronda w Górach Alterak.', '', '', '', '', 0),
(7382, 'koKR', 'Korrak Wiecznie Żywy', 'Coś tu jest nie tak... Czy ktoś w ogóle pomyślał, żeby spalić zwłoki Korraka? Te trolle nie cofną się przed niczym, żeby wskrzesić poległego przywódcę – jak to często mają w zwyczaju niebieskoskóre pogańskie człekobestie.$B$BPo prostu miej oczy otwarte, $N. Nie przejmuj się, jeśli Korrak niespodziewanie się pojawi, a jeśli tak się stanie, chcę, żeby go stracono – a jego zwłoki spalono na popiół.$B$BDla pewności utnij mu głowę i przynieś mi jego czaszkę, zanim podpalisz to martwe cielsko.', 'Jeśli Korrak Krwawy Szaleniec powróci na Pole Niezgody, odszukaj go i zabij.$B$BPrzynieś Czaszkę Korraka porucznikowi Haggerdinowi w Międzygórzu.$B', '', 'Wróć do porucznika Haggerdina na Wzgórzu Darrow w Międzygórzu.', '', '', '', '', 0),
(8234, 'koKR', 'Zapieczętowana lazurowa torba', 'Najpierw najważniejsze. Zgubiłem małą niebieską torbę, a jej zawartość to sprawa prywatna.$b$bNie trudź się ściganiem złodziei, bo już nie żyją. Wiemy natomiast, że ci głupcy nie zdołali otworzyć torby, więc sprzedali ją jakiemuś szamanowi Pyskodrzewnych w Aszarze jako świętą relikwię. Sprytne.$b$bMusisz udać się do Aszary i odebrać ją szamanowi – po cichu... albo siłą. Założę się, że pierwszy sposób da lepsze wyniki. Gdy ją zdobędziesz, zanieś ją arcymagowi Xylemowi.', 'Odbierz Zapieczętowaną lazurową torbę szamanowi Pyskodrzewnych w Aszarze. Następnie zanieś torbę arcymagowi Xylemowi, którego również znajdziesz w Aszarze.', '', 'Wróć do arcymaga Xylema przy Niedźwiedziej Głowie w Aszarze.', '', '', '', '', 0),
(8236, 'koKR', 'Lazurowy klucz', 'Odszyfrowanie fragmentów i zdjęcie zaklęcia zajmie trochę czasu. Gdy skończę, osobiście dostarczę torbę lordowi Ravenholdtowi.$b$bPozostaje jeszcze sprawa klucza, który podobno ma zielony smok zwany Morphazem. Smok zamieszkał głęboko w Świątyni Atal\'Hakkar, do której wejście leży na Moczarach Smutków.$b$bZbierz przyjaciół i wyrusz do jego leża. Lord Ravenholdt będzie czekał na twój powrót z kluczem.', 'Oddaj Lazurowy klucz lordowi Jorachowi Ravenholdtowi.', '', 'Wróć do lorda Joracha Ravenholdta we Dworze Krukowiska w Międzygórzu.', '', '', '', '', 0),
(8249, 'koKR', 'Potrzebne skrzynki z rupieciami', '', '', '', 'Wróć do Fahrada w Górach Alterak.', '', '', '', '', 0),
(8271, 'koKR', 'Bohater Gromdardy', '', '', '', '', '', '', '', '', 0),
(8272, 'koKR', 'Bohater Mroźnych Wilków', '', '', '', '', '', '', '', '', 0),
(8375, 'koKR', 'Pamiętaj o Dolinie Alterak!', 'Nie łudź się, $N. Horda ma całkowitą rację, gdy mówi, że Dolina Alterak to terytorium Mroźnych Wilków.$B$BWidzisz, Ekspedycja Gromdardy przybyła w te okolice jako pokojowi goście w poszukiwaniu rudy i relikwii. Mroźne Wilki odpowiedziały na to najbardziej brutalnym i barbarzyńskim aktem agresji, jakiego kiedykolwiek doświadczyło Przymierze.$B$BNigdy nie zapominajmy o dzielnych krasnoludach, które zginęły w tym tchórzliwym ataku bez wypowiedzenia wojny. Idź teraz, $N, i wypełnij swoją rolę w bitwie o Dolinę Alterak. Za Przymierze!', 'Przynieś 3 odznaki honoru Doliny Alterak generałowi brygady Przymierza poza polami bitew.', '', '', '', '', '', '', 0),
(8383, 'koKR', 'Pamiętaj o Dolinie Alterak!', '', '', '', '', '', '', '', '', 0),
(8387, 'koKR', 'Najeźdźcy w Dolinie Alterak', '', '', '', 'Wróć do zwiastuna wojny Hordy.', '', '', '', '', 0),
(8412, 'koKR', 'Totem ducha', 'Duchy żywiołów w tym miejscu już mnie nie lubić.$b$bTy znać się na totemach lepiej niż ktokolwiek, a ja potrzebować totemu ducha, żeby mnie chronił. Żywioły już mamy, teraz trzeba czegoś więcej z natury. Czegoś bardziej pierwotnego.$b$bNa Zachodnich Plagowiskach możesz zabijać niedźwiedzie dla pazurów i pająki dla oczu. Padlinożerne ptaki jedzą wszystko, więc mogą mieć jedno i drugie.', 'Przynieś części totemu ducha Bath\'rahowi Wiatrowidzowi.', '', '', '', '', '', '', 0),
(8413, 'koKR', 'Moc wudu', 'Totem ducha to za mało. Potrzebować trochę magii wudu, żeby działał jak trzeba.$b$bTrolle w zatopionej świątyni mają pióra pełne magii wudu. Idź tam i zabij Gashera, Mijana, Zola, Hukku, Zul\'lora i Lora. Wtedy mamy dość magii na prawdziwy totem ducha.', 'Przynieś pióra wudu Bath\'rahowi Wiatrowidzowi.', '', '', '', '', '', '', 0),
(9826, 'koKR', 'Kontakt z Dalaranu', 'Te znaki nie wróżą nam nic dobrego, $N. Nigdy nie lubiłem tajemnic, więc opowiem ci trochę o mojej organizacji, Purpurowym Oku.$B$BJesteśmy agentami Kirin Toru, Senatu Magów Dalaranu. Przydzielono nas do pilnowania Karazhanu i Medivha, na wypadek gdyby sprawy wymknęły się spod kontroli.$B$BI wymknęły się... bardzo szybko, gdy Medivh zniknął.$B$BTen raport zawiera moje ustalenia. Zanieś go arcymagowi Cedricowi, również z Purpurowego Oka. Znajdziesz go na obrzeżach Dalarańskiego Krateru.', 'Zanieś Raport Alturusa arcymagowi Cedricowi na obrzeżach Dalarańskiego Krateru.', '', '', '', '', '', '', 0),
(9829, 'koKR', 'Khadgar', 'Raport Alturusa jest niepokojący. Myśleliśmy, że jest źle, gdy Karazhan odciął się od świata zewnętrznego. Mieliśmy w środku agentów – nigdy więcej się nie odezwali. A teraz to... demoniczne promieniowanie. Musimy to zbadać.$B$BJedyne osoby, które mogą ponownie otworzyć Karazhan, uznano za zmarłe: Khadgar i Medivh.$B$BChoć mamy nadzieję, że ten drugi naprawdę odszedł, niedawno dowiedzieliśmy się, że jego uczeń, Khadgar, żyje i ma się dobrze w miejscu zwanym Shattrath. Znajdź go i przekaż mu raport Alturusa.', 'Dostarcz Raport Alturusa Khadgarowi w Shattrath w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(9860, 'koKR', 'Nowe wytyczne', 'Natychmiast wracaj do Cedrica, $N. Pomoc, której $gudzieliłeś:udzieliłaś; Purpurowemu Oku, nie pozostanie bez nagrody.$B$BMyśl o nas i naszej organizacji, co chcesz, $N, ale nie pożałujesz, że $gzyskałeś:zyskałaś; przychylność arcymagów Dalaranu.', 'Zgłoś się do arcymaga Cedrica na obrzeżach Dalarańskiego Krateru.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(535, 'koKR', 'Skoro zaraz umrę, mogę chyba śmiało powiedzieć, że to najsłodsza rzecz, jaką w życiu piłem... Masz, weź to, po śmierci i tak mi się nie przyda.$B$BNo, kończ już!', 0),
(602, 'koKR', 'Kamień Pływów? Nader interesujące. Może cię zaskoczy, że kilka lat temu napisałem księgę o legendach Imperium Gurubaszów. Wiem o tym Kamieniu całkiem sporo.$B$BPrzynajmniej na jednym z tych karwaszy widać ślady magii, które mogę przeanalizować.$B$BZobaczmy, co da się tu wyczytać...', 0),
(603, 'koKR', 'Mój sztylet? Co z ciebie za $gkomik:komiczka;?$B$BCo? Mam ci jeszcze raz opowiedzieć, jak z najlepszej nożowniczki w Łupieżczej Zatoce stałam się pośmiewiskiem całego pirackiego światka?!$B$BPrzegrałam walkę na noże z jednym z Krwawych Żagli – to banda skończonych drani! – a on zabrał mi ostrze jako łup.$B$BPrzecież nie utrzymam się jako nożowniczka samymi obelgami i ciętym językiem...', 0),
(1712, 'koKR', '$GZebrałeś:Zebrałaś; przedmioty do mojego zaklęcia i $gpokazałeś:pokazałaś; mi swoją siłę i przebiegłość. Ale kolejny etap naszej wyprawy jest jeszcze groźniejszy.$b$bMiejmy nadzieję, że siły cię nie opuszczą.', 0),
(1713, 'koKR', 'Udało ci się! $GPokonałeś:Pokonałaś; Cykloniana i $gzdobyłeś:zdobyłaś; Serce wiru!', 0),
(1714, 'koKR', 'Amulety powoli opadają w głąb kotła...$B$BNa powierzchnię cieczy wypływa wielki bąbel i pęka...$B$B...a w kotle ukazuje się kłębiąca się bryła roztopionej skały.', 0),
(1792, 'koKR', 'Mam serce wiru i mogę je umieścić w wybranym przez ciebie naczyniu.$B$BWybierz broń, $N, i wiedz, że jej moc to moc Cykloniana.', 0),
(6681, 'koKR', 'Znakomicie, $gmłody złodzieju:młoda złodziejko;.$B$BWyglądasz na nieco $gposiniaczonego:posiniaczoną;, ale nic ci nie jest.$B$BCzeka cię długa podróż – długa i owocna. Czy jesteś wreszcie $ggotów:gotowa; przyjąć swoje przeznaczenie wśród mistrzów Krukowiska?$B$BPorozmawiaj ze strażnikami na zewnątrz. Pomogą ci zacząć.', 0),
(7081, 'koKR', 'Dobra robota! Cmentarze są kluczowe dla naszej kontroli nad Doliną Alterak. Zdobywając je, pomagasz zapewnić tu zwierzchnictwo Przymierza.$B$BA teraz idź, $N. Wracaj do bitwy, a jeśli zobaczysz cmentarz w rękach Hordy... wiesz, co robić!', 0),
(7082, 'koKR', 'Dobra robota, $N! Z każdym cmentarzem, który przejmiemy, duchy naszych wrogów będą błąkać się coraz bardziej zagubione i bez celu.', 0),
(7101, 'koKR', 'Słyszałam o powodzeniu twojej misji! To mnie cieszy...$B$BNasze oddziały mogą teraz bezkarnie ruszyć naprzód i pokazać Przymierzu, że w Dolinie Alterak nie ma dla nich miejsca!', 0),
(7102, 'koKR', 'Dostałem raport z pola bitwy, że $gpomogłeś:pomogłaś; przejąć wrogi sztandar. Dobra robota, $N! Skoro ich oddziały dystansowe są poza pozycjami, możemy przesunąć linię frontu naprzód!', 0),
(7122, 'koKR', 'Udało ci się! Dobra robota, $N!$B$BGdy kontrolujemy kopalnię i stacjonują w niej nasze oddziały, o wiele łatwiej wydobywać z niej minerały i zapasy.', 0),
(7124, 'koKR', '$GPrzejąłeś:Przejęłaś; kopalnię! Skoro strzegą jej nasi wojownicy, o wiele łatwiej będzie wydobywać minerały z jej głębin albo zabierać zgromadzone tam zapasy.$B$BDobra robota, $n. Twój czyn to wielkie wsparcie dla naszych działań wojennych.', 0),
(7141, 'koKR', 'Dobra robota, $N! Skoro Horda dostała po nosie i straciła generała, będziemy mieć dość swobody, żeby prowadzić badania!', 0),
(7142, 'koKR', 'Dobra robota, $N! Gromdarda nie ma szans w tej głupiej inwazji.$B$BHa! Jak dotąd jedyne, co im się udało, to dać zabić własnego generała!', 0),
(7161, 'koKR', 'To palące uczucie, które czujesz, to budząca się dusza. Twój duch przyjął wezwanie do broni.$B$BJesteś teraz $gjednym:jedną; z Mroźnych Wilków, $N. Gratulacje.$B$BNoś te insygnia zawsze przy sobie. W miarę jak będziesz awansować w szeregach Mroźnych Wilków, będę je wymieniać na inne, potężniejsze.$B$BMoże pewnego dnia zyskasz najwyższą cześć w Klanie Mroźnego Wilka. Jeśli ten dzień kiedyś nadejdzie, otrzymasz Oko Dowodzenia.', 0),
(7162, 'koKR', 'Weź te insygnia i noś je z dumą, $N. W miarę jak będziesz awansować w szeregach Gromdardy, insygnia będą rosły razem z tobą. Wracaj do mnie, gdy zdobędziesz honor u Gromdardy, a wymienię twoje insygnia na inne, potężniejsze.$B$BMoże pewnego dnia staniesz się legendą tego pola bitwy. Jeśli ten dzień kiedyś nadejdzie, otrzymasz Oko Dowodzenia.', 0),
(7163, 'koKR', 'Te nowe insygnia odzwierciedlają twoją rangę wśród Mroźnych Wilków. Noś je zawsze przy sobie.$B$BA ty, magu... Giń z honorem!', 0),
(7164, 'koKR', '<Mistrz wojenny Laggrond salutuje.>$B$BIdź, $N! Broń dalej Mroźnych Wilków. Tę wojnę trzeba wygrać! Za Drek\'Thara! Za wodza!', 0),
(7165, 'koKR', 'Gdy się poznaliśmy, nigdy bym nie zgadł, że rośnie tu $gbohater:bohaterka;. Tak trzymaj, $gżołnierzu:żołnierko;!', 0),
(7166, 'koKR', 'Wkrótce wszyscy na polu bitwy znajdą się pod twoim czujnym okiem. Dowództwo nad Doliną i jej oddziałami będzie należeć do ciebie!', 0),
(7167, 'koKR', 'Skup moc insygniów. Niech wróg usłyszy twoje słowa. Potęga Hordy jest niepodważalna!', 0),
(7168, 'koKR', 'Niech nasi wrogowie zobaczą, że powalił ich żołnierz wysokiej rangi! Walcz o chwałę Gromdardy!', 0),
(7169, 'koKR', 'Król dowiedział się o twoich bohaterskich czynach na froncie, $N. Wytrwale broń dalej Straży Gromdardy!', 0),
(7170, 'koKR', 'Gdy się poznaliśmy, nigdy bym nie zgadł, że rośnie tu $gbohater:bohaterka;. Tak trzymaj, $gżołnierzu:żołnierko;!', 0),
(7171, 'koKR', 'Wkrótce wszyscy na polu bitwy znajdą się pod twoim czujnym okiem. Dowództwo nad Doliną i jej oddziałami będzie należeć do ciebie!', 0),
(7172, 'koKR', 'To ty musisz poprowadzić nasze oddziały do zwycięstwa, $gdowódco:dowódczyni;! Żołnierze są pod twoją komendą. Będą wykonywać twoje bezpośrednie rozkazy. Poprowadź ich... Zmiażdż Mroźne Wilki.', 0),
(8234, 'koKR', 'Widzę, że masz torbę lorda Ravenholdta. Czemu od razu tak nie $gmówiłeś:mówiłaś;, $gchłopcze:dziewczyno;?', 0),
(8236, 'koKR', 'Klucz! Myślałem, że przepadł na zawsze. Proszę, weź zaczarowany strój z moich zapasów – są przeznaczone dla łotrów o wyjątkowych umiejętnościach i lojalności. Niech wszyscy wiedzą, że z $N nie ma żartów!$B$B<Jorach otwiera torbę i zalewa go złota poświata bijąca z jej wnętrza. Jego oczy się rozszerzają i wpatruje się w nią...>', 0),
(8249, 'koKR', 'Niech te noże znajdą miejsce w czyimś sercu.$b$bDosłownie.', 0),
(8271, 'koKR', 'Jako $gbohater:bohaterka; Gromdardy możesz wybrać jeden przedmiot z tych niedawno zrabo... ekhm, odzyskanych skarbów.', 0),
(8272, 'koKR', 'Jak się czujesz, $N? Jak to jest miażdżyć wrogów i patrzeć, jak ich szeregi się rozpadają? Dobre uczucie, co?$b$bZa ten bohaterski czyn należy ci się nagroda, $gżołnierzu:żołnierko;.', 0),
(8375, 'koKR', '$GWykazałeś:Wykazałaś; się wielką odwagą, broniąc naszych ziem w Dolinie Alterak! Opowiem przełożonym o twoich czynach.', 0),
(8383, 'koKR', 'Nadal przynosisz Przymierzu chlubę, $N. Jeśli nie ustaniemy w wysiłkach, Horda wkrótce zostanie zmiażdżona.', 0),
(8387, 'koKR', 'Dobra robota, $N! Możesz być z siebie $gdumny:dumna;. Najeźdźców z Przymierza trzeba wypędzić z Alterak!', 0),
(8412, 'koKR', 'Świetnie, mon! Wypróbujmy go...', 0),
(8413, 'koKR', 'Najwyższy czas, żeby ten troll porządnie się wyspał! Totem ducha będzie nade mną czuwał.$B$BDługo zbierać różne rzeczy, może chcesz coś za swój trud?', 0),
(9826, 'koKR', 'Wiesz o Purpurowym Oku? Nie wyglądasz znajomo.', 0),
(9829, 'koKR', 'Purpurowe Oko? Nie mów.$B$BPokaż mi ten raport, o którym mówisz.', 0),
(9860, 'koKR', 'Alturus opowiedział mi o wszystkim, co się wydarzyło, $N. To jednak jeszcze nie koniec. Skoro Karazhan pozostaje zamknięty dla obcych, to tylko kwestia czasu, aż Legion wznowi ataki, a my będziemy bezsilnie przyglądać się z boku.$B$BChyba że przyjmiesz odpowiedzialność, którą złożył na ciebie los.$B$B<Cedric wyciąga ku tobie otwartą dłoń, na której leży odznaka z symbolem Purpurowego Oka.>$B$BCo ty na to, $N?', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(535, 'koKR', '$GPrzyniosłeś:Przyniosłaś; mi coś do picia czy $gwróciłeś:wróciłaś; tylko, żeby mnie dobić?', 0),
(602, 'koKR', 'Jeśli pozwolisz, jestem teraz dość zajęty.', 0),
(1712, 'koKR', 'Masz te przedmioty, $N? Ich zebranie to dowód, którego potrzebuję – dowód, że masz dość siły, by stawić czoła Cyklonianowi.', 0),
(1713, 'koKR', '$N, muszę mieć serce wiru!', 0),
(1714, 'koKR', 'Kocioł bulgocze. Jego opary kuszą...', 0),
(6681, 'koKR', '$GPoznałeś:Poznałaś; Miltona?<Fahrad się śmieje.>', 0),
(7081, 'koKR', '$N, nie $gzaatakowałeś:zaatakowałaś; jeszcze cmentarza. Wróć do mnie, gdy wykonasz to zadanie!', 0),
(7082, 'koKR', 'Zaatakuj cmentarz należący do Przymierza!', 0),
(7101, 'koKR', 'Nie $gzaatakowałeś:zaatakowałaś; jeszcze bunkra, $N! Czekasz, aż inni zgarną twoją chwałę?', 0),
(7102, 'koKR', 'Nie $gzaatakowałeś:zaatakowałaś; jeszcze wieży, $N! Na co czekasz?', 0),
(7122, 'koKR', 'Nie $gprzejąłeś:przejęłaś; jeszcze kopalni, $N!$B$BGdy będziemy kontrolować kopalnię, o wiele łatwiej będzie wydobywać z niej minerały i zapasy.', 0),
(7124, 'koKR', 'Nie $gprzejąłeś:przejęłaś; jeszcze kopalni, $N! Znajdź taką, której nie kontrolujemy, i pokonaj jej przywódcę!', 0),
(7141, 'koKR', 'Idź, $N. Idź do Doliny Alterak i pokonaj orczego generała!', 0),
(7161, 'koKR', 'Obudź się! Obudź się, $N! To nie sen. Naprawdę tkwisz w samym środku szalejącej bitwy!', 0),
(7162, 'koKR', 'Strzeż się tutejszych harpii, $N. Bez wahania rozszarpią ci gardło!', 0),
(7168, 'koKR', 'Większość nie żyje dość długo, by wznieść się ponad własną przeciętność. $GUdowodniłeś:Udowodniłaś;, że jesteś $gwzorowym żołnierzem:wzorową żołnierką;, $N. Nadszedł czas.$B$BPokaż swoje insygnia.', 0),
(7169, 'koKR', 'Cała baza huczy od wieści o twoich wyczynach na Polu Niezgody! $GZadałeś:Zadałaś; wrogowi potężne ciosy i $gzłamałeś:złamałaś; jego ducha! Za to $gzasłużyłeś:zasłużyłaś; na honorową rangę wśród Gromdardy.$B$BPokaż swoje insygnia.', 0),
(7170, 'koKR', 'Muszę to wiedzieć, $n. Gdy patrzysz wrogowi prosto w oczy, czy widzisz w nich strach? Czy kulą się teraz w twojej obecności? Muszą zrozumieć, że są pokonani!$B$B$GZasłużyłeś:Zasłużyłaś; na cześć w szeregach Straży. Pokaż swoje insygnia!', 0),
(7171, 'koKR', 'Stoi przede mną $gwysławiony bohater:wysławiona bohaterka; Przymierza.$B$B<Porucznik Haggerdin salutuje.>$B$BNiewielu zasłużyło na taką rangę wśród Gromdardy. Widziałem, jak wrogowie padają przed tobą. Widziałem, jak ich determinacja kruszy się w twojej obecności. Gdy wkraczasz do walki, stajesz się latarnią nadziei dla naszych sił!$B$BPokaż swoje insygnia.', 0),
(7172, 'koKR', 'Niech usłyszą twój głos, $gdowódco:dowódczyni; $n! Niech poznają strach. Pokaż im, jaką potęgę kryją szeregi Gromdardy!$B$BPokaż swoje insygnia.', 0),
(8236, 'koKR', 'Torba już dotarła od arcymaga Xylema. $GZnalazłeś:Znalazłaś; klucz?', 0),
(8249, 'koKR', 'Moi łotrzy muszą szlifować umiejętność otwierania zamków, a ja potrzebuję zamków o odpowiedniej trudności – to, co robi nam Zan, nadaje się tylko dla najbardziej zielonych nowicjuszy.$b$bWiesz co? Jeśli przyniesiesz mi 5 ciężkich skrzynek z rupieciami, dam ci jedne z najlepszych noży do rzucania, jakie zna łotrowski świat.$b$bMożesz otworzyć skrzynki i w nich pogrzebać, ale musisz zostawić w nich przynajmniej kilka monet... nawet łotr na szkoleniu potrzebuje motywacji.', 0),
(8375, 'koKR', 'Jakie wieści przynosisz z ziem Gromdardy? Jak przebiega bitwa o Dolinę Alterak?', 0),
(8387, 'koKR', 'Jakie wieści przynosisz z ziem Mroźnych Wilków? Jak przebiega bitwa o Dolinę Alterak?', 0),
(8412, 'koKR', 'Duchy wiedzą, co kombinujemy, i próbują mnie zabić! Mam nadzieję, że masz te części.', 0),
(8413, 'koKR', 'Gdzie pióra, mon?', 0),
(9826, 'koKR', 'Alturus powierzył ci te informacje? Stary głupiec.$B$BCóż, co się stało, to się nie odstanie, równie dobrze możemy zrobić z ciebie użytek. Przypuszczam, że zechcesz współpracować?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(8379, 0, 'koKR', 'Jeśli przychodzisz błagać o przywilej pracy dla mnie, twoje towarzystwo jest jak najbardziej mile widziane. W przeciwnym razie raczej nie masz szans mi się do czegokolwiek przydać.', 0),
(186420, 1, 'koKR', 'Ten zbiór zwojów zawiera różne informacje logistyczne i strategiczne, a także zaszyfrowaną korespondencję.', 0);
