INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(266, 'koKR', 'Kegan Darkmar, przywódca niewielkiej grupy nieumarłych, którzy przybyli do nas, szukając azylu przed swoimi „braćmi”, przeczy powszechnym wyobrażeniom o swoim gatunku. Jego skóra może gnić, a krew dawno przestała płynąć w jego żyłach, lecz zachowuje się bardzo szlachetnie i zdaje się bardziej troszczyć o bezpieczeństwo towarzyszy niż o własne.$B$BZaiste, jest w nim człowieczeństwo, którego – wyznaję – czasem brakuje mi u ludzi wokół mnie.', 0),
(267, 'koKR', 'Czemu jednak o tym wspominam? Robię to, by uwiarygodnić to, co zaraz zapiszę, bo słowa te padły z ust Kegana, a mam nadzieję, że moi koledzy po lekturze tego dziennika zrozumieją, czemu wierzę w to, co powiedział:$B$B„Pozostałości Przedwiecznych wciąż trwają w głębokich czeluściach świata. Nowe siły chcą zaprząc tę pradawną moc, a ci, którym się to uda, zyskają straszliwą broń przeciw swoim wrogom”.', 0),
(268, 'koKR', 'Tak rzekł Kegan, wręczając mi swój wisior z krwawnika, a w jego oczach był strach, a może i cześć. Gdy jego dłonie zetknęły się z moimi, zawahały się, jakby niechętnie oddawały wisior. Przeszyło mnie obrzydzenie, a do dziś nie wiem, czy brzydziło mnie jego martwe ciało przyciśnięte do mojego, czy to sam wisior sprawiał, że cierpła mi skóra.$B$BWyczułam bowiem w nim moc. Głęboką, ukrytą, wygłodniałą moc. Moc, która pragnęła się uwolnić.', 0),
(269, 'koKR', 'Choć moi koledzy w Dalaranie z ostrożnością podchodzili do badania krwawników, które przynieśli ze sobą Kegan i jego zwolennicy – zamiast tego poddali czwórkę uchodźców kwarantannie, a krwawniki zostawili przy nich – szczerość Kegana skłoniła mnie do zbadania jego wisiora z krwawnika.', 0),
(270, 'koKR', 'Chciałam potwierdzić kolegom, że ten rodzaj kamienia rzeczywiście ma właściwości magiczne i że jeśli my, czarodzieje z Dalaranu, nie chcemy wykorzystywać mocy krwawników, powinniśmy przynajmniej poznać ich właściwości, bo pewnego dnia wrogowie mogą ich użyć przeciwko nam.$B$BTak rozpoczęły się moje badania.', 0),
(271, 'koKR', 'Zaczęłam testy od założenia, że krwawnik to rodzaj skały, jak kwarc czy obsydian. Rozpoczęłam więc serię procedur, by ustalić, jakie minerały zawiera krwawnik, jakie siły nadały mu barwę i twardość, oraz inne właściwości typowe dla skał i rud. Ku mojej frustracji wisior z krwawnika nie reagował jednak na moje procedury tak jak zwykła ruda.', 0),
(272, 'koKR', 'W istocie często zachowywał się dokładnie odwrotnie, niż się spodziewałam! Zupełnie jakby wisior celowo psuł moje eksperymenty.$B$BJakby myślał i żył.$B$BRozgniewana, lecz nie zniechęcona, porzuciłam założenie, że wisior to bezwładny kawałek skały, i przyjęłam, że to żywa istota.$B$BLecz znów poniosłam porażkę.', 0),
(273, 'koKR', 'Żaden z nowych testów nie rzucił światła na pochodzenie krwawnika. Wówczas jedyną zagadką, jaką rozwiązałam, było to, że krwawnik nie jest ani żywy, ani martwy!$B$BAle właśnie wtedy, na skraju porażki, nastąpił przełom. W ostatnim teście użyłam szklanej zlewki z wyszczerbionym brzegiem, na którym została niewielka, postrzępiona szczerba. Gdy test się zakończył, znów niczego nie wykazując, zabrałam się do sprzątania stołu roboczego i skaleczyłam się o zlewkę.', 0),
(274, 'koKR', 'Rana nie była głęboka, ale mimo to mocno krwawiła. Zanim zdążyłam owinąć zraniony palec bandażem, sporo mojej krwi rozlało się na stół.$B$BI kiedy sprzątałam ten nowy bałagan, zauważyłam coś niezwykle dziwnego...', 0),
(275, 'koKR', 'Krew, która rozlała się w pobliżu wisiora z krwawnika, powoli przesuwała się w stronę klejnotu, jakby grawitacja w jakiś sposób zakrzywiła się ku krwawnikowi. Krew, która dotknęła wisiora, zdawała się znikać, a czerwień kamienia pogłębiała się, w miarę jak pił coraz więcej mojej krwi.', 0),
(276, 'koKR', 'Po tym widoku zakręciło mi się w głowie – może przez świeżą ranę (choć nie sądziłam, że straciłam aż tyle krwi), a może dlatego, że po tylu frustracjach w końcu odkryłam jedną z właściwości krwawnika. Sięgnęłam za siebie po stołek i usiadłam, pogrążona w rozmyślaniach. Myśli i pytania gnały mi przez głowę, przyprawiając o zawrót i grożąc, że zwalą mnie z nóg.$B$BCzy krwawnik pije krew? Czy łaknie krwi? Czy przyciąga krew?', 0),
(277, 'koKR', 'A może krwawnik jest zrobiony z krwi? A jeśli tak, to czyjej? Mojej? Krwi każdego człowieka? Każdego zwierzęcia?$B$BA może krwawnik to krew jakiejś nieznanej istoty – tej samej, której Kegan zarazem się bał i którą czcił, gdy wręczał mi swój wisior.$B$BNa to pytanie trzeba znaleźć odpowiedź. To jest klucz.', 0),
(278, 'koKR', 'Z nowym zapałem rzuciłam się z powrotem w wir eksperymentów. Tym razem nie przyjmowałam żadnych założeń, metodycznie przeprowadzając każdy dostępny test. Ogromnie zwiększyło to nakład pracy, ale dawało większą szansę na odkrycia.$B$BI choć moje laboratorium jest tu małe, a nie mam podwładnych, których mogłabym oddelegować do pomocy, odkryłam jeszcze jedną intrygującą właściwość krwawnika...', 0),
(279, 'koKR', 'Oprócz krwi w kamieniu stopione są siły żywiołów. Ogień, woda, grom i skała mieszają się z krwią (ale znów – z krwią czego?),\n a choć z zewnątrz ta mieszanina jest bezwładna, wszystkie te siły zdają się wewnątrz zażarcie ze sobą walczyć. Pojawiło się wtedy o wiele więcej pytań na temat tego zdumiewającego i złowieszczego materiału.', 0),
(280, 'koKR', 'Aby jednak odpowiedzieć na te pytania, trzeba przeprowadzić na wisiorze więcej badań i eksperymentów, a obawiam się, że Obóz Internowania Lordamere nie dysponuje ani ludźmi, ani sprzętem do tego zadania. Wysłałam więc wisior z krwawnika z kurierem do Dalaranu wraz ze szczegółowymi instrukcjami, jak go badać, by oszczędzić tamtejszym badaczom moich wcześniejszych frustracji.', 0),
(281, 'koKR', 'Czekając na wyniki tych testów, spędzałam czas na rozmowach z Keganem. Choć nieustannie wypytywałam go o to, co wie o krwawnikach, nigdy nie powiedział mi więcej niż tego dnia, gdy dał mi swój wisior. Rzadko też mówił o czasie spędzonym w szeregach tych, których nazywał „Porzuconymi” – tak nazywa swój klan nieumarłych.', 0),
(282, 'koKR', 'Kegan chętnie za to rozmawiał o innych sprawach, zwłaszcza o dorastaniu w Lordaeronie przed jego upadkiem.$B$BWciąż darzy wielką miłością to utracone królestwo, choć jest ono teraz zrujnowane i martwe.$B$BRosnąca sympatia do Kegana dodawała mi cierpliwości w oczekiwaniu na wyniki testów.', 0),
(283, 'koKR', 'Lecz po tygodniach bez wieści moja cierpliwość się wyczerpała, a gdy dopytałam w Dalaranie, dowiedziałam się, że krwawnik nigdy nie dotarł do moich kolegów. Mój kurier jakimś sposobem zaginął w drodze, a wraz z nim przepadł wisior z krwawnika!$B$BTo poważna wiadomość, bo choć Kegan i jego zwolennicy wciąż mają okazy krwawnika, na których możemy prowadzić badania, obawiam się, że wisior może wpaść w niepowołane ręce.', 0),
(284, 'koKR', 'Wysłałam do Dalaranu kolejnego posłańca i słyszę, że nawet teraz przeczesują ruiny poza naszą ochronną kopułą w poszukiwaniu wisiora.$B$BMam tylko nadzieję, że nie jest za późno.', 0),
(855, 'koKR', 'Poniżej znajdziesz to, czego potrzeba do mojego zaklęcia przyzwania wielkiego Cykloniana. Niech szczęście ci sprzyja.$B$B– Bath\'rah Wiatrowidz', 0),
(856, 'koKR', 'Korzeń życia:\n\nMożna go zebrać w dziczy albo zdobyć od bestii z Więdnących Pnączy na Pyłowym Bagnisku. Jego moc będzie niezbędna, by przyciągnąć esencję życiową Cykloniana do tego świata.', 0),
(857, 'koKR', 'Kły Krwawych Skalpów:\n\nKły trolli z Krwawych Skalpów w Dolinie Cierniodławów mają rzadką właściwość. Zepsucie Krwawych Skalpów skupia się w ich kłach, a po zmieleniu na proszek można uwolnić ich plugawą moc.', 0),
(858, 'koKR', 'Esencja wygnańca:\n\nTę esencję uzyskuje się przez połączenie trzech amuletów wygnanych żywiołaków z Wyżyn Aratorskich. Zbierz od żywiołaków grzmiące, płonące i wzbierające amulety, a następnie umieść po osiem z każdego rodzaju w moim kotle.\n\nZ amuletów powstanie esencja wygnańca.', 0),
(2771, 'koKR', 'Obieranie cebuli$BPoradnik rozbierania Gromdardy na części$B– autor: Drek\'Thar$B$BNa tych stronach znajdziesz bogactwo wiedzy o taktyce bitewnej i polityce. Uczony żołnierz to żołnierz, który wspiera się na ramieniu doświadczenia. Niech ta księga będzie twoim przewodnikiem w bitwie o Dolinę Alterak.$B', 0),
(2772, 'koKR', 'Rozdział 1 – Linia frontu$B$BRozbieranie armii Gromdardy przypomina obieranie cebuli. Aby dotrzeć do środka, trzeba zacząć od zdjęcia zewnętrznych warstw.$B$BLinie frontu, złożone głównie z górskich strażników Gromdardy i strażników Przymierza, są powiązane z bunkrem kapitan. To kapitan Balinda Stonehearth wzmacnia te oddziały i zapewnia posiłki, gdy linie są oblegane. Uderz w kapitan, a siły z linii frontu się rozsypią.$B$B', 0),
(2773, 'koKR', 'Rozdział 2 – Bliźniacze wieże$B$BNie łudź się: Vandar Gromdarda to przebiegły wróg i z pewnością nie głupiec. Gdy linia frontu zostanie przełamana, trzeba jeszcze zniszczyć drugorzędne cele obronne. To bliźniacze wieże Skałogorców i Lodowego Skrzydła kierują gwardzistami Gromdardy poza Dun Baldar oraz patrolami Gromdardy.', 0),
(2774, 'koKR', 'Strzeż się, żołnierzu, bo obie wieże są silnie ufortyfikowane i dowodzi nimi jeden z elitarnych dowódców Vandara. Jeśli twoje siły przełamią umocnienia, upewnij się, że dowódca w środku został... uciszony. To także część rozbierania Gromdardy.$B', 0),
(2775, 'koKR', 'Rozdział 3 – Czterej dowódcy$B$BTrzecią warstwę cebuli Gromdardy stanowią czterej dowódcy. Pod tym względem Vandar naśladuje naszą wspaniałą obronę Mroźnych Wilków. Oczywiście on twierdzi inaczej... Ale odbiegam od tematu.$B$BCzterej dowódcy kierują przypływami i odpływami gwardzistów Gromdardy, którzy zaciekle strzegą Dun Baldar. Ucisz ich wszystkich, a gwardziści Gromdardy padną.$B$BWtedy zostanie już tylko jedna warstwa do obrania.$B', 0),
(2776, 'koKR', 'Rozdział 4 – Bunkry Dun Baldar$B$BJak z pewnością nie uszło twojej uwadze, warstwy obrony Gromdardy mają zapobiec temu, by jeden potężny ruch rozbił całą armię. Zanim zapytasz: tak, dokładnie tak rozmieszczone są nasze własne siły, i nie, nie zmienię naszej struktury obronnej. To oni nas skopiowali, czemu to my mielibyśmy coś zmieniać?$B', 0),
(2777, 'koKR', 'Na czym to ja skończyłem? A tak: bunkry Dun Baldar (które znajdują się w Dun Baldar) kierują obrońcami Gromdardy – najbardziej zaufanymi i elitarnymi strażnikami Vandara. Zniszcz te dwie wieże, a posiłki wysyłane na pomoc Vandarowi przestaną istnieć.', 0),
(2778, 'koKR', 'Epilog$B$BGdy już to wszystko zrobisz, zostanie ci środek cebuli: słodki rdzeń. Vandar Gromdarda zostanie sam i bezbronny. Zasady wojskowego postępowania wymagają, byśmy przed wykonaniem egzekucji wezwali go do kapitulacji. Nie zapomnij wspomnieć o tej kapitulacji, gdy go zobaczysz... a potem go zabij.', 0),
(2779, 'koKR', 'Karczoch Mroźnych Wilków: Opowieści o chwale Gromdardy\n– autor: Vandar Gromdarda\n\nCzym są Mroźne Wilki? Odpowiedź jest prosta: Mroźne Wilki to dzikusy, które próbują powstrzymać nasz suwerenny imperialistyczny imperatyw.\n\nZupełnie jak karczoch, Mroźne Wilki mają kolczastą, osłoniętą obronę i zupełnie jak w karczochu, gdy zdejmie się zewnętrzną warstwę, odsłania się serce, gotowe do zjedzenia z wybornym sosem czosnkowym.\n\nPyszności!\n', 0),
(2780, 'koKR', 'Rozdział 1 – Linia frontu\n\nLinię frontu obrony Mroźnych Wilków tworzą wojownicy Mroźnych Wilków. Wojownicy są wysyłani na front z fortecy kapitana Galvangara: Garnizonu Lodowej Posoki. Najskuteczniejszym sposobem na zlikwidowanie tej warstwy obrony jest zniszczenie Garnizonu Lodowej Posoki.\n\nObleż fortecę i zabij kapitana Galvangara. Gdy to zrobisz, linia frontu się rozsypie.\n', 0),
(2781, 'koKR', 'Rozdział 2 – Lodowa Posoka i Wieżowy Cypel\n\nGdy pierwsza warstwa padnie, odsłoni się druga warstwa „karczocha”. Zniszczenie wież Mroźnych Wilków, które stoją w pobliżu linii frontu, sparaliżuje legionistów i patrole, które roją się na tyłach.\n\nWieże są silnie ufortyfikowane, a w każdej przebywa jeden z elitarnych dowódców Drek\'Thara. Trzeba ich zabić. To przyspieszy rozbieranie obrony Mroźnych Wilków.', 0),
(2782, 'koKR', 'Rozdział 3 – Czterej dowódcy\n \nJeśli postępujesz zgodnie z mądrościami tego poradnika, to dwaj dowódcy Drek\'Thara są już martwi. Dobra robota, żołnierzu! Ich determinacja już słabnie. Teraz musisz dokończyć rozbijanie łańcucha dowodzenia, zabijając pozostałych dwóch dowódców.\n\nGdy wszyscy czterej dowódcy zginą, legioniści Mroźnych Wilków, którzy strzegą Twierdzy Mroźnych Wilków, rozproszą się – pozbawieni dowództwa. Jak dojrzałe owoce do zerwania!\n', 0),
(2783, 'koKR', 'Rozdział 4 – Wschodnia i Zachodnia Wieża Mroźnych Wilków\n\nMiędzy tobą a zwycięstwem stoi już tylko jedna warstwa: najbardziej zaufani i najpotężniejsi strażnicy Drek\'Thara – strażnicy Mroźnych Wilków.\n\nStrażnicy Mroźnych Wilków są wysyłani z plutonów trzymanych w odwodzie we wschodniej i zachodniej wieży Mroźnych Wilków. Zniszcz te wieże i patrz, jak pozostali strażnicy Mroźnych Wilków uciekają ze wstydem.', 0),
(2784, 'koKR', 'Epilog\n\n„Zalej serce karczocha masłem czosnkowym i majonezem. Do posiłku podaj leżakowane, mocne piwo”.\n\nDrek\'Thar zostaje teraz sam, z dwoma kundlami u boku. Zdobądź Szpital polowy Mroźnych Wilków, by wesprzeć swoją walkę, i zniszcz Drek\'Thara. Gdy generał padnie, ta ziemia wreszcie przejdzie w ręce swojego prawowitego właściciela: Gromdardy.\n', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(605, 'koKR', 'Mmm... Uwielbiam mój pyszny porter z Południowego Brzegu.', '', 0),
(606, 'koKR', 'Porterze z Południowego Brzegu, jakże cię kocham? Pozwól, że wyliczę...', '', 0),
(761, 'koKR', 'Jakie to ciekawe... Kamień ma ogromny potencjał magiczny, ale w zupełnie surowej postaci...', '', 0),
(1365, 'koKR', '', 'Sidney się spóźnia. Myślałam, że będzie już w domu.', 0),
(1366, 'koKR', 'To twój mąż, kobieto. Skąd mam wiedzieć, gdzie jest?', '', 0),
(1367, 'koKR', '', 'Pewnie ma w Klasztorze urwanie głowy. Ale mimo wszystko powinien już wrócić.', 0),
(1368, 'koKR', 'Oczyszczanie świata z nieczystych szumowin to niełatwa robota, Nancy. Ktoś musi to robić.', '', 0),
(1369, 'koKR', '', 'No to wyjdę sprawdzić. Coś jest nie tak.', 0),
(1370, 'koKR', '', '%s wydaje z siebie długie, przeciągłe westchnienie.', 0),
(1371, 'koKR', '', 'No cóż....', 0),
(7494, 'koKR', '$GPrzyszedłeś:Przyszłaś; uczyć się od mistrza, co?', '$GPrzyszedłeś:Przyszłaś; uczyć się od mistrza, co?', 0),
(7495, 'koKR', 'Tak. Naucz mnie.', 'Tak. Naucz mnie.', 0),
(7496, 'koKR', 'Wyglądam ci na kogoś, kto szkoli takich jak ty? Zmykaj, zanim najdzie mnie ochota naoliwić ostrze... twoją krwią.', 'Wyglądam ci na kogoś, kto szkoli takich jak ty? Zmykaj, zanim najdzie mnie ochota naoliwić ostrze... twoją krwią.', 0),
(8493, 'koKR', 'Śmiesz postawić stopę we Dworze Krukowiska, robaku?', 'Śmiesz postawić stopę we Dworze Krukowiska, robaku?', 0),
(8494, 'koKR', 'Wyjście stąd bez ostrza w plecach albo trucizny w żyłach byłoby nie lada wyczynem.', 'Wyjście stąd bez ostrza w plecach albo trucizny w żyłach byłoby nie lada wyczynem.', 0),
(8528, 'koKR', 'Wszyscy jesteśmy elementami o wiele większej układanki, $n. Tak jak ty prowadzisz element układanki na jego miejsce, tak i nas prowadzi ktoś inny.$B$BA może ci, którzy nas prowadzą, sami są prowadzeni przez jeszcze większą siłę.', '', 0),
(10191, 'koKR', '', '$GPrzyszedłeś:Przyszłaś; się uczyć, co? Może i mam dla ciebie jakąś robotę, żółtodziobie.', 0),
(10192, 'koKR', '<Sierżant Gromdarda salutuje.>$B$BImię, stopień i numer służbowy, $gżołnierzu:żołnierko;! To jedyne informacje, jakie kiedykolwiek przekażesz tym parszywym psom z Mroźnych Wilków!', '', 0),
(10481, 'koKR', 'Przykro mi, $N, ale musisz nabrać więcej doświadczenia, zanim zdołasz przetrwać w Dolinie Alterak.', 'Przykro mi, $N, ale musisz nabrać więcej doświadczenia, zanim zdołasz przetrwać w Dolinie Alterak.', 0),
(14935, 'koKR', 'Nie daj się zwieść otaczającym nas ruinom, $N. Dalaran jest potężny jak zawsze.', '', 0),
(14936, 'koKR', 'Karazhan to coś więcej niż zwykła budowla, $n. Gdyby prześledzić linie mocy przecinające Azeroth, okazałoby się, że wszystkie zbiegają się mniej więcej w tamtym miejscu.$B$B<Alturus wskazuje niewidoczny punkt pod wieżą.>$B$BFascynujące, prawda?', '', 0),
(14937, 'koKR', 'Arcymag Alvareux napisał kiedyś traktat, w którym badał fascynującą teorię. Zakładał istnienie dokładnej kopii Karazhanu w innym świecie niż nasz, przy czym obie miałyby w jakiś sposób zajmować tę samą przestrzeń.$B$BWkrótce potem postradał zmysły. Wielka szkoda.', '', 0),
(14939, 'koKR', 'Mądrość naaru przekracza nasze pojmowanie. Przez ostatnie pięć miesięcy A\'dal nauczył mnie więcej niż wszystkie lata spędzone w bibliotekach Dalaranu.', '', 0),
(17154, 'koKR', 'Twoje imię wymawia się tylko szeptem, magu. Kim jesteś?', 'Twoje imię wymawia się tylko szeptem, magu. Kim jesteś?', 0),
(17155, 'koKR', 'Jestem Khadgar, niegdyś uczeń poległego Strażnika, Medivha. Na pewno $gsłyszałeś:słyszałaś; już jego imię.$B$BTo ja odkryłem, że Medivh był opętany przez Złego, Sargerasa – i że to on otworzył Mroczny Portal między tym światem a Azeroth. Choć czciłem mojego mistrza, musiałem go zabić i dać spokój jego udręczonej duszy.', '', 0),
(17157, 'koKR', 'Walczyłem u boku lorda Anduina Lothara, gdy wypędzaliśmy Hordę z naszych ziem w Azeroth. Jako dziedzic spuścizny Medivha nie mogłem postąpić inaczej.$B$BGdy wreszcie nadeszło wezwanie do inwazji na ten posępny świat – by raz na zawsze położyć kres złu orków – zgłosiłem się wraz z moimi przyjaciółmi: Turalyonem, Allerią, Danathem i Kurdranem.', '', 0),
(17158, 'koKR', 'Ja i moi towarzysze nazwaliśmy się Synami Lothara – na cześć największego i najbardziej bezinteresownego człowieka, jakiego znaliśmy. Daliśmy z siebie wszystko, by pokonać Ner\'zhula i położyć kres jego szaleństwu.$B$BGdy ten skazany na zagładę świat rozpadał się wokół nas, zniszczyliśmy Mroczny Portal, by nic więcej nie zagroziło naszemu ukochanemu Azeroth.', '', 0),
(17159, 'koKR', 'Uwięzieni na tym rozbitym pustkowiu, robiliśmy, co mogliśmy, by przetrwać. Z czasem wyczuliśmy, że z Wypaczonej Otchłani zbliża się ku nam nowe zło. Plugawsze niż mroczni orkowie – to sam Płonący Legion chciał zawładnąć tą... Rubieżą.', '', 0),
(17160, 'koKR', 'Gdy moi towarzysze powstrzymywali napierającą ciemność, ja sięgnąłem magią w Bezkresną Ciemność. Wyczułem tam istoty niezmierzonej Światłości – o niepojętej czystości.$B$BZnalazłem A\'dala i jego naaru. To był prawdziwy... cud.', '', 0),
(17161, 'koKR', '<Khadgar uśmiecha się pod nosem.>$B$BPrzekonałem A\'dala i jego braci, by wrócili tu ze mną. Wierzę, że tylko ich moc zdoła wypędzić Legion z tego wszechświata. Ale jak na pewno się przekonasz – ich moc musi najpierw zamieszkać w naszych sercach.$B$BAby walczyć z ciemnością, musimy stać się latarniami ich wiecznej Światłości.', '', 0),
(17238, 'koKR', 'Nie zawracaj A\'dalowi głowy przyziemnymi pytaniami. Tylko wola tej istoty powstrzymuje naszych wrogów przed zmiażdżeniem tego miasta.', '', 0),
(17266, 'koKR', 'Oprowadź naszego gościa po Shattrath, dobrze? I uważaj na kieszonkowców w Dolnym Mieście.', '', 0),
(17748, 'koKR', 'A co ty tu robisz?! Zabieraj swoje gadatliwe cztery litery do Doliny Alterak, tam cię potrzebują!', '', 0),
(17749, 'koKR', '', 'DZICZE ŁAJNO! Czemu muszę tu sterczeć i kierować innych do Doliny Alterak, zamiast samemu tam walczyć? Ty! $GPrzyszedłeś:Przyszłaś; walczyć z Przymierzem?', 0),
(18743, 'koKR', 'Co było dalej?', 'Co było dalej?', 0),
(18745, 'koKR', '$GChciałem:Chciałam; cię jeszcze o coś zapytać.', '$GChciałem:Chciałam; cię jeszcze o coś zapytać.', 0),
(19574, 'koKR', 'Mów dalej, proszę.', 'Mów dalej, proszę.', 0),
(60156, 'koKR', 'Rozumiem.', 'Rozumiem.', 0);
